17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import org.springframework.samples.petclinic.model.Owner;
20	import org.springframework.samples.petclinic.service.ClinicService;
21	import org.springframework.stereotype.Component;
22	
23	/**
24	 * Detects, on create, whether a new owner duplicates an already-stored one. All duplicate
25	 * detection is consolidated into the owner's {@link Owner#getIdentityKey() identity key}
26	 * (telephone, email and household id combined): a candidate is a duplicate only when an
27	 * existing owner carries the exact same identity key. Because the telephone is part of the
28	 * key, owners that differ in any one of those parts — including two members of the same
29	 * household with different telephones — have distinct keys and are not duplicates.
30	 */
31	@Component
32	public class IdentityDuplicateChecker {
33	
34	    private final ClinicService clinicService;
35	
36	    public IdentityDuplicateChecker(ClinicService clinicService) {
37	        this.clinicService = clinicService;
38	    }
39	
40	    /**
41	     * Reports whether an already-stored owner shares {@code candidate}'s identity key.
42	     *
43	     * @param candidate the owner being created, not yet stored
44	     * @return {@code true} when another owner already carries the same identity key
45	     */
46	    public boolean isDuplicate(Owner candidate) {
47	        String identityKey = candidate.getIdentityKey();
48	        return clinicService.findAllOwners().stream()
49	            .filter(existing -> !existing.isDeleted())
50	            .anyMatch(existing -> existing.getIdentityKey().equals(identityKey));
51	    }
52	}
