16	package org.springframework.samples.petclinic.model;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	
22	/**
23	 * SHA-256 helper producing the leading upper-case hex characters of a value's digest.
24	 */
25	public final class Sha256Hex {
26	
27	    private Sha256Hex() {
28	    }
29	
30	    /**
31	     * The first {@code length} upper-case hex characters of the SHA-256 digest of the
32	     * UTF-8 bytes of {@code value}.
33	     *
34	     * @param value  the string to hash
35	     * @param length how many leading hex characters to return
36	     * @return the leading {@code length} upper-case hex characters of the digest
37	     */
38	    public static String prefix(String value, int length) {
39	        byte[] digest = digest(value);
40	        StringBuilder sb = new StringBuilder(length + 1);
41	        for (int i = 0; sb.length() < length; i++) {
42	            sb.append(String.format("%02X", digest[i]));
43	        }
44	        return sb.substring(0, length);
45	    }
46	
47	    private static byte[] digest(String value) {
48	        try {
49	            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
50	        }
51	        catch (NoSuchAlgorithmException ex) {
52	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
53	        }
54	    }
55	}
