18	
19	import java.util.Optional;
20	import java.util.regex.Pattern;
21	
22	import org.springframework.samples.petclinic.model.CountryDialingCode;
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Canonicalises an owner telephone number to E.164 form.
27	 * <p>
28	 * Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
29	 * kept when present; otherwise the {@link #DEFAULT_COUNTRY_CODE default country code} is
30	 * assumed and a single leading {@code '0'} is dropped from the national digits. The result
31	 * is a {@code '+'} followed by {@link #MIN_DIGITS}-{@link #MAX_DIGITS} digits, so numbers
32	 * that differ only in formatting or in the way their country code is written are stored and
33	 * compared identically.
34	 * <p>
35	 * For {@link #NATIONAL_LENGTHS known country codes} the national number (the digits after
36	 * the country code) must additionally carry the exact number of digits that country uses
37	 * (e.g. {@code '+61'} requires 9 national digits, {@code '+1'} requires 10); a number whose
38	 * national part is the wrong length for its country is rejected.
39	 */
40	@Component
41	public class TelephoneNormalizer {
42	
43	    /** Country code assumed when the number carries no explicit {@code '+'} prefix. */
44	    public static final String DEFAULT_COUNTRY_CODE = "61";
45	
46	    /** The fewest digits a valid E.164 number carries after the {@code '+'}. */
47	    public static final int MIN_DIGITS = 8;
48	
49	    /** The most digits a valid E.164 number carries after the {@code '+'}. */
50	    public static final int MAX_DIGITS = 15;
51	
52	    /** Separators removed before interpreting the number: spaces, dashes and brackets. */
53	    private static final Pattern SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
54	
55	    /**
56	     * Converts a raw telephone into its canonical E.164 representation.
57	     *
58	     * @param raw the telephone as supplied by the client, possibly {@code null}
59	     * @return the E.164 number ({@code '+'} then {@value #MIN_DIGITS}-{@value #MAX_DIGITS}
60	     *         digits), or empty when {@code raw} cannot form a valid E.164 number
61	     */
62	    public Optional<String> toE164(String raw) {
63	        if (raw == null) {
64	            return Optional.empty();
65	        }
66	        String stripped = SEPARATORS.matcher(raw).replaceAll("");
67	        String digits = stripped.startsWith("+")
68	            ? stripped.substring(1)
69	            : DEFAULT_COUNTRY_CODE + dropLeadingZero(stripped);
70	        return isValid(digits) ? Optional.of("+" + digits) : Optional.empty();
71	    }
72	
73	    private String dropLeadingZero(String national) {
74	        return national.startsWith("0") ? national.substring(1) : national;
75	    }
76	
77	    private boolean isValid(String digits) {
78	        return digits.chars().allMatch(c -> c >= '0' && c <= '9')
79	            && digits.length() >= MIN_DIGITS && digits.length() <= MAX_DIGITS
80	            && hasValidNationalLength(digits);
81	    }
82	
83	    /**
84	     * Checks the national-number length for a known country code. Numbers whose leading
85	     * digits match no known country code pass this check, relying on the generic bounds.
86	     */
87	    private boolean hasValidNationalLength(String digits) {
88	        return CountryDialingCode.matching(digits)
89	            .flatMap(code -> CountryDialingCode.nationalLength(code)
90	                .map(length -> digits.length() - code.length() == length))
91	            .orElse(true);
92	    }
93	}
