18	
19	import java.util.Locale;
20	import java.util.Set;
21	
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Recognises email addresses whose domain belongs to a known disposable-email provider.
26	 * <p>
27	 * Disposable domains are throwaway mailboxes unsuitable for owner contact, so an address on
28	 * one of these domains is rejected rather than stored.
29	 */
30	@Component
31	public class DisposableEmailDomainChecker {
32	
33	    private static final Set<String> DISPOSABLE_DOMAINS =
34	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
35	
36	    /**
37	     * @param email an email address as supplied by the client
38	     * @return {@code true} when the address's domain is on the disposable-domain blocklist
39	     */
40	    public boolean isDisposable(String email) {
41	        if (email == null) {
42	            return false;
43	        }
44	        int at = email.lastIndexOf('@');
45	        if (at < 0) {
46	            return false;
47	        }
48	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
49	        return DISPOSABLE_DOMAINS.contains(domain);
50	    }
