18	
19	import java.util.Comparator;
20	import java.util.Optional;
21	
22	import org.springframework.samples.petclinic.model.Owner;
23	import org.springframework.samples.petclinic.service.ClinicService;
24	import org.springframework.stereotype.Component;
25	
26	/**
27	 * Finds, on create, an already-stored owner that a new owner softly matches: one that
28	 * shares the new owner's last name (compared ignoring case) and postcode while carrying a
29	 * different (already normalized) telephone. This is a weaker signal than the outright
30	 * {@link IdentityDuplicateChecker identity duplicate} that rejects a create; a soft match
31	 * merely flags the created owner as a possible duplicate. An owner with no postcode can
32	 * never softly match, since a shared postcode is part of the rule.
33	 */
34	@Component
35	public class PossibleDuplicateMatcher {
36	
37	    private final ClinicService clinicService;
38	
39	    public PossibleDuplicateMatcher(ClinicService clinicService) {
40	        this.clinicService = clinicService;
41	    }
42	
43	    /**
44	     * Returns the earliest-created already-stored owner that softly matches
45	     * {@code candidate}, or empty when there is none.
46	     *
47	     * @param candidate the owner being created, not yet stored
48	     * @return the matched owner, or empty
49	     */
50	    public Optional<Owner> findMatch(Owner candidate) {
51	        if (candidate.getPostcode() == null || candidate.getPostcode().isBlank()) {
52	            return Optional.empty();
53	        }
54	        return clinicService.findAllOwners().stream()
55	            .filter(existing -> softlyMatches(existing, candidate))
56	            .min(Comparator.comparing(Owner::getId));
57	    }
58	
59	    private boolean softlyMatches(Owner existing, Owner candidate) {
60	        return candidate.getPostcode().equals(existing.getPostcode())
61	            && equalsIgnoreCase(existing.getLastName(), candidate.getLastName())
62	            && !equals(existing.getTelephone(), candidate.getTelephone());
63	    }
64	
65	    private boolean equalsIgnoreCase(String a, String b) {
66	        return a == null ? b == null : a.equalsIgnoreCase(b);
67	    }
68	
69	    private boolean equals(String a, String b) {
70	        return a == null ? b == null : a.equals(b);
71	    }
72	}
