167	    /**
168	     * Collects the distinct names of the fields that failed validation, preserving the order in
169	     * which they were reported.
170	     *
171	     * @param bindingResult the result carrying the field errors
172	     * @return the rejected field names, without duplicates
173	     */
174	    private List<String> rejectedFieldNames(BindingResult bindingResult) {
175	        return bindingResult.getFieldErrors().stream()
176	            .map(FieldError::getField)
177	            .distinct()
178	            .toList();
